fn step_params(sm: &SM, tr: &Transition) -> TokenStream {
    let skip_n = if expect_first_param_is_label(sm, tr) { 1 } else { 0 };

    let params: Vec<TokenStream> = tr
        .params
        .iter()
        .skip(skip_n)
        .map(|param| {
