            let f = crate::to_relation::to_is_enabled_condition_weak(&simplified_body);

            let rel_fn = quote_vstd! { vstd =>
                #[cfg(verus_keep_ghost_body)]
                #[verus::internal(verus_macro)]
                #[verifier::spec]
                #[verus::internal(open)] /* vattr */
